/// Returns (F(n), F(n + 1)), where F(0) = 0 and F(1) = 1.
fn fib_pair(n: u32) -> (u64, u64) {
    let (mut a, mut b) = (0, 1);
    for _ in 0..n {
        (a, b) = (b, a + b);
    }
    (a, b)
}

fn main() {
